import pty, os, time, select

def try_passwd(newpw, label):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp("su", ["su", "-", "pwtestuser", "-c", "passwd"])
    else:
        out = b""
        deadline = time.time() + 6
        sent1 = sent2 = False
        while time.time() < deadline:
            r, _, _ = select.select([fd], [], [], 0.5)
            if fd in r:
                try:
                    chunk = os.read(fd, 4096)
                except OSError:
                    break
                if not chunk:
                    break
