                    os.write(fd, newpw + b"\n")
                    sent1 = True
                elif sent1 and not sent2 and out.count(b"password") >= 2:
                    os.write(fd, newpw + b"\n")
                    sent2 = True
        try:
            os.kill(pid, 9)
        except OSError:
            pass
        print(f"=== {label} ===")
        print(out.decode(errors='replace'))

